\",\"frames\":16000,\"sample_rate\":16000}},\"object_id\":\"00000000-0000-4000-8000-000000001051\",\"ordinal\":1},{\"bytes\":{\"byte_count\":24,\"content_type\":\"video/mp4\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"},\"facts\":{\"image\":null,\"mp4\":{\"structure\":\"bounded_mp4_accepted\"},\"wav\":null},\"object_id\":\"00000000-0000-4000-8000-000000001052\",\"ordinal\":2}],\"profile_digest\":\"bcc4b8c18220ff9ad645a3306cf230442327f00412d380119bff798e8b5c15ad\",\"scan_id\":\"00000000-0000-4000-8000-000000001002\",\"validator_identity\":\"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\",\"version\":1},\"version\":2}","outcome_digest":"476e879d1732fd444fddfe76b044d4348643ceb04f7228bcf743e28d579cb970"}]}$vectors$::JSONB v;
CREATE TEMP TABLE qualified_cases AS SELECT row_number() OVER() i,x v FROM qualified_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') x;
CREATE FUNCTION pg_temp.qualified_context(v JSONB) RETURNS JSONB LANGUAGE SQL AS $$
 SELECT internal.initial_qualified_context(internal.initial_canonical(v->'candidate'),v->>'assignment_canonical',internal.initial_canonical(v#>'{catalog,preparation}'),internal.initial_canonical(v#>'{catalog,installation}'),internal.initial_canonical(v#>'{catalog,protocol}'),internal.initial_canonical(v#>'{catalog,destination}'));
$$;
SELECT extensions.lives_ok(format('SELECT pg_temp.qualified_context(%L::JSONB)',v),'qualified context '||i) FROM qualified_cases;
SELECT extensions.is(internal.initial_preparation_digest('assignment',v->>'assignment_canonical'),v->>'assignment_digest','original assignment domain '||i) FROM qualified_cases;
SELECT extensions.lives_ok(format('SELECT internal.assert_initial_qualified_outcome(%L,pg_temp.qualified_context(%L::JSONB),%L,%L)',v#>>'{outcome,scan_id}',v,v->>'original_expires_at_ms',v->>'outcome_canonical'),'whole mixed-version outcome '||i) FROM qualified_cases;
SELECT extensions.is(internal.initial_qualified_outcome_digest(v->>'outcome_canonical'),v->>'outcome_digest','outcome v2 digest '||i) FROM qualified_cases;
SELECT extensions.is(internal.valid_initial_media_assignment_pair(internal.initial_canonical(v->'candidate'),v->>'assignment_canonical'),FALSE,'legacy v2 validator rejects qualified v3 '||i) FROM qualified_cases;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_preparation_execution(%L,%L)','outcome',v->>'outcome_canonical'),'22023','initial_analysis_input_invalid','old outcome codec does not widen '||i) FROM qualified_cases;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_qualified_codec(%L,%L)','outcome',internal.initial_canonical(jsonb_set(v->'outcome',ARRAY[k,'version'],'2'))),'22023','initial_analysis_input_invalid','nested receipt remains v1 '||k||i) FROM qualified_cases CROSS JOIN unnest(ARRAY['source_verification','output_manifest','resolved_manifest']) k;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_qualified_codec(%L,%L)','grant',internal.initial_canonical((v#>'{outcome,grant}')-k)),'22023','initial_analysis_input_invalid','new grant field required '||k) FROM qualified_cases CROSS JOIN unnest(ARRAY['handoff_profile_digest','handoff_installation_digest','protocol_artifact_digest','handoff_total_ms','preparation_expires_at_ms','preparation_wall_ms']) k WHERE i=1;
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_qualified_grant(%L,pg_temp.qualified_context(%L::JSONB),%L,%L,%L)',v#>>'{outcome,scan_id}',v,v->>'source_digest',v->>'original_expires_at_ms',internal.initial_canonical(jsonb_set(v#>'{outcome,grant}',ARRAY[k],to_jsonb(repeat('0',64))))),'22023','initial_analysis_input_invalid','new digest binding '||k) FROM qualified_cases CROSS JOIN unnest(ARRAY['handoff_profile_digest','handoff_installation_digest','protocol_artifact_digest']) k WHERE i=1;
SELECT extensions.throws_ok(format('SELECT pg_temp.qualified_context(%L::JSONB)',jsonb_set(v,'{assignment_canonical}',to_jsonb(internal.initial_canonical(jsonb_set(v->'assignment','{handoff,installation_digest}',to_jsonb(repeat('0',64))))))),'22023','initial_analysis_input_invalid','installation substitution') FROM qualified_cases WHERE i=1;
CREATE TEMP TABLE qualified_boundary AS SELECT v,(v#>>'{outcome,grant,issued_at_ms}')::BIGINT+45000+(v#>>'{outcome,grant,preparation_wall_ms}')::BIGINT+(v#>>'{outcome,grant,handoff_total_ms}')::BIGINT e FROM qualified_cases WHERE i=1;
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_qualified_grant(%L,pg_temp.qualified_context(%L::JSONB),%L,%L,%L)',v#>>'{outcome,scan_id}',v,v->>'source_digest',e,internal.initial_canonical(jsonb_set(v#>'{outcome,grant}','{preparation_expires_at_ms}',to_jsonb(e)))),'22023','initial_analysis_input_invalid','strict expiry equality rejects') FROM qualified_boundary;
SELECT extensions.lives_ok(format('SELECT internal.assert_initial_qualified_grant(%L,pg_temp.qualified_context(%L::JSONB),%L,%L,%L)',v#>>'{outcome,scan_id}',v,v->>'source_digest',e+1,internal.initial_canonical(jsonb_set(v#>'{outcome,grant}','{preparation_expires_at_ms}',to_jsonb(e+1)))),'one millisecond strict margin passes declaration validation') FROM qualified_boundary;
SELECT extensions.throws_ok(format('SELECT internal.assert_initial_qualified_grant(%L,pg_temp.qualified_context(%L::JSONB),%L,%L,%L)',v#>>'{outcome,scan_id}',v,v->>'source_digest',e+1,internal.initial_canonical(jsonb_set(v#>'{outcome,grant}','{preparation_expires_at_ms}',to_jsonb(e+2)))),'22023','initial_analysis_input_invalid','payload cannot choose original expiry') FROM qualified_boundary;
SELECT extensions.lives_ok($q$SELECT internal.parse_initial_qualified_codec('reply_held','{"authority":"none","outcome":"held","reason":"handoff_qualification_unavailable","version":2}')$q$,'explicit v2 refusal');
SELECT extensions.throws_ok($q$SELECT internal.parse_initial_preparation_execution('reply_held','{"authority":"none","outcome":"held","reason":"handoff_qualification_unavailable","version":2}')$q$,'22023','initial_analysis_input_invalid','refusal does not widen v1');
SELECT extensions.ok(NOT has_function_privilege(r,s,'EXECUTE'),'no ordinary helper access '||r||s) FROM unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY['internal.initial_qualified_schema()','internal.parse_initial_qualified_codec(text,text)','internal.initial_qualified_context(text,text,text,text,text,text)','internal.assert_initial_qualified_grant(uuid,jsonb,text,numeric,text)','internal.assert_initial_qualified_source(uuid,jsonb,text)','internal.assert_initial_qualified_output(uuid,jsonb,jsonb,text)','internal.assert_initial_qualified_resolved(uuid,jsonb,jsonb,text)','internal.assert_initial_qualified_outcome(uuid,jsonb,numeric,text)','internal.initial_qualified_outcome_digest(text)']) s;
SELECT extensions.is((SELECT initial_analysis_lifecycle_enabled FROM internal.initial_analysis_rollout),FALSE,'activation remains false');

CREATE FUNCTION pg_temp.context_result(args TEXT[],original BOOLEAN) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE v JSONB;
BEGIN
 IF original THEN v:=pg_temp.original_qualified_context(args[1],args[2],args[3],args[4],args[5],args[6]);
 ELSE v:=internal.initial_qualified_context(args[1],args[2],args[3],args[4],args[5],args[6]); END IF;
 RETURN jsonb_build_object('value',v);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('sqlstate',SQLSTATE,'message',SQLERRM);
END; $$;
CREATE TEMP TABLE context_inputs AS SELECT i,ARRAY[
 internal.initial_canonical(v->'candidate'),v->>'assignment_canonical',
 internal.initial_canonical(v#>'{catalog,preparation}'),internal.initial_canonical(v#>'{catalog,installation}'),
 internal.initial_canonical(v#>'{catalog,protocol}'),internal.initial_canonical(v#>'{catalog,destination}')
] AS args FROM qualified_cases;
SELECT extensions.is(pg_temp.context_result(args,FALSE),pg_temp.context_result(args,TRUE),'exact original context result '||i) FROM context_inputs;
CREATE FUNCTION pg_temp.changed_context_args(args TEXT[],arg_index INTEGER,replacement TEXT) RETURNS TEXT[] LANGUAGE PLPGSQL AS $$
BEGIN args[arg_index]:=replacement; RETURN args; END; $$;
SELECT extensions.is(
 pg_temp.context_result(pg_temp.changed_context_args(args,arg_index,replacement),FALSE),
 pg_temp.context_result(pg_temp.changed_context_args(args,arg_index,replacement),TRUE),
 'same rejection '||i||' argument '||arg_index||' case '||ordinality)
FROM context_inputs CROSS JOIN generate_series(1,6) arg_index
CROSS JOIN LATERAL unnest(ARRAY[NULL::TEXT,'','{','null','{}','[]',' '||args[arg_index],args[arg_index]||' ',repeat('x',1048577)]) WITH ORDINALITY x(replacement,ordinality);
SELECT extensions.is(
 pg_temp.context_result(pg_temp.changed_context_args(args,2,internal.initial_canonical(jsonb_set(args[2]::JSONB,ARRAY['handoff',field],to_jsonb(repeat('0',64))))),FALSE),
 pg_temp.context_result(pg_temp.changed_context_args(args,2,internal.initial_canonical(jsonb_set(args[2]::JSONB,ARRAY['handoff',field],to_jsonb(repeat('0',64))))),TRUE),
 'exact relationship rejection '||i||field)
 FROM context_inputs CROSS JOIN unnest(ARRAY['profile_digest','installation_digest']) field;
SELECT extensions.is(
 pg_temp.context_result(pg_temp.changed_context_args(args,arg_index,internal.initial_canonical(jsonb_set(args[arg_index]::JSONB,ARRAY[field],to_jsonb(repeat('0',64))))),FALSE),
 pg_temp.context_result(pg_temp.changed_context_args(args,arg_index,internal.initial_canonical(jsonb_set(args[arg_index]::JSONB,ARRAY[field],to_jsonb(repeat('0',64))))),TRUE),
 'catalog digest rejection '||i||arg_index||field)
 FROM context_inputs CROSS JOIN (VALUES(4,'profile_digest'),(4,'protocol_artifact_digest'),(4,'preparation_profile_digest')) edits(arg_index,field);
SELECT extensions.is(
 pg_temp.context_result(pg_temp.changed_context_args(pg_temp.changed_context_args(args,first_pos,'{'),second_pos,NULL),FALSE),
 pg_temp.context_result(pg_temp.changed_context_args(pg_temp.changed_context_args(args,first_pos,'{'),second_pos,NULL),TRUE),
 'multiple invalid precedence '||i||first_pos||second_pos)
 FROM context_inputs CROSS JOIN generate_series(1,6) first_pos CROSS JOIN generate_series(1,6) second_pos WHERE first_pos<second_pos;


CREATE FUNCTION pg_temp.context_expected(args TEXT[],expect_valid BOOLEAN) RETURNS BOOLEAN LANGUAGE PLPGSQL AS $$
DECLARE original JSONB:=pg_temp.context_result(args,TRUE); proposed JSONB:=pg_temp.context_result(args,FALSE);
BEGIN
 RETURN original IS NOT DISTINCT FROM proposed AND CASE WHEN expect_valid THEN
  original ? 'value' AND proposed ? 'value' AND jsonb_typeof(original->'value')='object'
 ELSE original ? 'sqlstate' AND proposed ? 'sqlstate' END;
END; $$;
SELECT extensions.ok(pg_temp.context_expected(args,TRUE),'valid context returns object '||i) FROM context_inputs;
SELECT extensions.ok(pg_temp.context_expected(pg_temp.changed_context_args(args,arg_index,replacement),FALSE),'invalid argument denied '||i||':'||arg_index||':'||ordinality)
FROM context_inputs CROSS JOIN generate_series(1,6) arg_index
CROSS JOIN LATERAL unnest(ARRAY[NULL::TEXT,'','{','null','{}','[]',' '||args[arg_index],args[arg_index]||' ',repeat('x',1048577)]) WITH ORDINALITY x(replacement,ordinality);
SELECT extensions.ok(pg_temp.context_expected(pg_temp.changed_context_args(args,2,internal.initial_canonical(jsonb_set(args[2]::JSONB,ARRAY['handoff',field],to_jsonb(repeat('0',64))))),FALSE),'invalid handoff relationship denied '||i||field)
FROM context_inputs CROSS JOIN unnest(ARRAY['profile_digest','installation_digest']) field;
SELECT extensions.ok(pg_temp.context_expected(pg_temp.changed_context_args(args,arg_index,internal.initial_canonical(jsonb_set(args[arg_index]::JSONB,ARRAY[field],to_jsonb(repeat('0',64))))),FALSE),'invalid catalog relationship denied '||i||field)
FROM context_inputs CROSS JOIN (VALUES(4,'profile_digest'),(4,'protocol_artifact_digest'),(4,'preparation_profile_digest')) edits(arg_index,field);
SELECT extensions.ok(pg_temp.context_expected(pg_temp.changed_context_args(pg_temp.changed_context_args(args,first_pos,'{'),second_pos,NULL),FALSE),'multiple invalid denied '||i||':'||first_pos||':'||second_pos)
FROM context_inputs CROSS JOIN generate_series(1,6) first_pos CROSS JOIN generate_series(1,6) second_pos WHERE first_pos<second_pos;


CREATE FUNCTION pg_temp.direct_context_result(kind TEXT,args TEXT[],original BOOLEAN) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE value BOOLEAN;
BEGIN
 IF kind='pair' THEN
  IF original THEN value:=pg_temp.original_media_assignment_pair(args[1],args[2]);
  ELSE value:=internal.valid_initial_media_assignment_pair(args[1],args[2]); END IF;
 ELSE
  IF original THEN PERFORM pg_temp.original_media_profile_matches(args[1],args[2]);
  ELSE PERFORM internal.assert_initial_media_profile_matches(args[1],args[2]); END IF;
  value:=TRUE;
 END IF;
 RETURN jsonb_build_object('value',value);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('sqlstate',SQLSTATE,'message',SQLERRM);
END; $$;
CREATE FUNCTION pg_temp.direct_context_matches(kind TEXT,args TEXT[],valid BOOLEAN) RETURNS BOOLEAN LANGUAGE PLPGSQL AS $$
DECLARE expected JSONB:=pg_temp.direct_context_result(kind,args,TRUE); actual JSONB:=pg_temp.direct_context_result(kind,args,FALSE);
BEGIN
 RETURN expected IS NOT DISTINCT FROM actual AND CASE WHEN valid THEN actual->'value'='true'::JSONB
 ELSE actual ? 'sqlstate' OR actual->'value'='false'::JSONB END;
END; $$;
CREATE TEMP TABLE direct_context_inputs AS
 SELECT i,'pair'::TEXT kind,ARRAY[args[1],internal.initial_canonical(jsonb_set(args[2]::JSONB-'handoff','{version}','2'))] args FROM context_inputs
 UNION ALL SELECT i,'profile',ARRAY[args[1],args[3]] FROM context_inputs;
SELECT extensions.ok(pg_temp.direct_context_matches(kind,args,TRUE),'direct entry valid '||kind||i) FROM direct_context_inputs;
SELECT extensions.ok(pg_temp.direct_context_matches(kind,pg_temp.changed_context_args(args,arg_index,replacement),FALSE),'direct entry denial '||kind||i||':'||arg_index||':'||ordinality)
FROM direct_context_inputs CROSS JOIN generate_series(1,2) arg_index
CROSS JOIN LATERAL unnest(ARRAY[NULL::TEXT,'','{','null','{}','[]',' '||args[arg_index],args[arg_index]||' ',repeat('x',1048577)]) WITH ORDINALITY x(replacement,ordinality);
SELECT extensions.ok(pg_temp.direct_context_matches(kind,pg_temp.changed_context_args(args,2,internal.initial_canonical(jsonb_set(args[2]::JSONB,ARRAY[field],to_jsonb(repeat('0',64))))),FALSE),'direct pair relationship denial '||i||field)
FROM direct_context_inputs CROSS JOIN unnest(ARRAY['candidate_digest','source_plan_digest']) field WHERE kind='pair';
SELECT extensions.ok(NOT has_function_privilege(role_name,signature,'EXECUTE'),'private parsed helper denied '||role_name||signature)
FROM unnest(ARRAY['anon','authenticated','service_role']) role_name
CROSS JOIN unnest(ARRAY['internal.initial_media_assignment_pair_values(text,text,jsonb)','internal.assert_initial_media_profile_values(jsonb,jsonb)']) signature;
SELECT extensions.ok(NOT p.prosecdef AND p.provolatile='s' AND p.proconfig=ARRAY['search_path=""']
 AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE'),
 'parsed helper is stable invoker with empty search path and no PUBLIC execution '||p.proname)
FROM pg_proc p WHERE p.oid IN ('internal.initial_media_assignment_pair_values(text,text,jsonb)'::regprocedure,'internal.assert_initial_media_profile_values(jsonb,jsonb)'::regprocedure);

SELECT * FROM extensions.finish();
ROLLBACK;
